import json,sys,html,shutil,xml.etree.ElementTree as ET
from pathlib import Path
W=Path(__file__).parent;ROOT=W.resolve().parents[2];sys.path.insert(0,str(ROOT))
from icon_set.model.icons.registry import create
rows=json.loads((W/'audit.json').read_text());assets=W/'review-assets';assets.mkdir(exist_ok=True);cards=[]
for r in rows:
 n=r['number'];before=create(r['icon']).to_svg();source=Path(r['source_path']);has_source=source.exists()
 original=source.read_text() if has_source else before
 candidate=create(r['candidate']).to_svg() if r.get('candidate') else before
 canvas_width=int(ET.fromstring(candidate).get('width','32'))
 for name,data in [('original',original),('before',before),('after',candidate)]:
  (assets/f'{n}-{name}.svg').write_text(data)
 tree=ET.fromstring(candidate)
 for el in tree.iter():
  if el.get('stroke'):el.set('stroke','#afbbc3')
 for el in list(tree):
  if el.tag.rsplit('}',1)[-1] in ('path','line','polyline','polygon','circle','ellipse','rect'):
   clone=ET.fromstring(ET.tostring(el));clone.set('stroke','#087bd8');clone.set('stroke-width','.22');clone.set('fill','none');tree.append(clone)
 (assets/f'{n}-center.svg').write_bytes(ET.tostring(tree))
 def fig(kind,label,cls=''):
  return f'<figure class="{cls}" style="--cw:{canvas_width}"><figcaption>{label}</figcaption><img loading="lazy" src="review-assets/{n}-{kind}.svg" alt="{html.escape(r["icon"])}"></figure>'
 source_label='Original source' if has_source else 'Previous model · source missing'
 result_label='Repaired' if r['outcome']=='repaired' else ('Unaccepted draft' if r.get('candidate') else 'Unresolved · previous model')
 cards.append(f'''<article data-outcome="{r['outcome']}" id="icon-{n}"><h2>{n}. {html.escape(r['icon'])}</h2><span class="badge {r['outcome']}">{'Repaired · geometry checks pass' if r['outcome']=='repaired' else 'Unresolved · not activated'}</span><div class="previews">{fig('original',source_label)}{fig('before','Before')}{fig('after',result_label,'grid')}{fig('center',f'Centerline · {canvas_width}×32','grid')}</div><div class="native">{fig('after','32px · light')}{fig('after','32px · dark','dark')}</div><p>{html.escape(r['reason'])}</p><button class="enlarge">Enlarge / compare</button><details><summary>Source parts and checks</summary><p>{html.escape(r['source_parts'])}</p><pre>{html.escape(str(r.get('candidate_findings','Original failure retained; see source-coverage note.')))}</pre><p>Source UUID: {r['source_uuid']}<br>Previous Python file preserved. {('Linked new profile: '+r['candidate']) if r['outcome']=='repaired' else 'No replacement activated.'}</p></details></article>''')
fixed=sum(r['outcome']=='repaired' for r in rows)
summary=json.loads((ROOT/'icon_set/work/side-repair-priority/summary.json').read_text())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>50 side-combination sub-icons · repair review</title><style>
*{box-sizing:border-box}body{margin:0;background:#eff2f0;color:#24332f;font:14px system-ui}header{padding:20px 24px;background:#fff;border-bottom:1px solid #d9e1dc}h1{font-size:24px;margin:0 0 8px}.counts{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.counts span{padding:8px 12px;background:#f1f4f2;border-radius:6px}.counts .good,.badge.repaired{background:#dcf4e6;color:#18623b}.counts .bad,.badge.unresolved{background:#fbe6df;color:#a13a23}header p{max-width:950px;line-height:1.5;margin:8px 0;color:#56675f}input,select,button{font:inherit;background:#fff;border:1px solid #bdcbc2;border-radius:5px;padding:7px 10px}button{cursor:pointer}.controls{display:flex;gap:8px;flex-wrap:wrap}main{padding:20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(590px,100%),1fr));gap:16px}article{background:#fff;padding:18px;border-radius:9px;min-width:0}article[hidden]{display:none}h2{font-size:15px;margin:0 0 10px;overflow-wrap:anywhere}.badge{display:inline-block;padding:5px 8px;border-radius:5px;font-size:12px}.previews{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:14px}figure{margin:0;min-width:0;background:#f7f9f8;border-radius:5px;display:flex;flex-direction:column;align-items:center;gap:8px;padding:8px}figcaption{font-size:10px;color:#54665d;text-align:center;min-height:24px}img{display:block;width:128px;height:128px;max-width:100%;object-fit:contain}.grid img{height:auto;background-color:#fff;background-image:linear-gradient(#526b7912 1px,transparent 1px),linear-gradient(90deg,#526b7912 1px,transparent 1px),linear-gradient(#526b791e 1px,transparent 1px),linear-gradient(90deg,#526b791e 1px,transparent 1px);background-size:calc(100% / var(--cw)) 3.125%,calc(100% / var(--cw)) 3.125%,calc(800% / var(--cw)) 25%,calc(800% / var(--cw)) 25%}.native{display:flex;gap:8px;margin-top:8px}.native figure{min-width:110px}.native img{width:auto;height:32px;max-width:none}.dark{background:#182a31}.dark img{filter:brightness(0) invert(1)}.dark figcaption{color:#dae8df}article p{font-size:13px;line-height:1.5}details{margin-top:12px}pre{white-space:pre-wrap;font-size:11px;line-height:1.5}dialog{width:min(1100px,96vw);max-height:96vh;overflow:auto;border:0;border-radius:10px;padding:20px}dialog::backdrop{background:#13241bc9}dialog .close{float:right;position:sticky;top:0;z-index:2}dialog .previews{grid-template-columns:repeat(2,minmax(0,1fr))}dialog .previews img{width:256px;height:256px}dialog .previews .grid img{height:auto}dialog .enlarge{display:none}a{color:#216d4b}@media(max-width:600px){.previews{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:10px}}
</style><header><h1>50 side-combination sub-icons · repair review</h1>'''+f'''<div class="counts"><span>50 inspected</span><span class="good">{fixed} repaired</span><span class="bad">{50-fixed} unresolved</span><span>{summary["repair_or_review"]} side sub-icons still need repair / review</span></div><p>Selected from <strong>failed side-combination sub-icons</strong>, ranked by waiting combinations. Container symbols are excluded. Repaired drawings retain the original parts, use 4px strokes, and pass model and export checks. Standard 32px drawings also pass container-circle checks. Side-library progress: {summary["statuses"]["pass"]} of 825 passing; {summary["statuses"]["fail"]} failed checks and {summary["statuses"]["review"]} review warnings remain. No human approval is implied.</p><p>Unresolved entries remain in the failure queue. Their originals and any attempted redraws are shown separately. All 50 original sources are included. Grid and centerline overlays are display guides.</p>'''+'''<div class="controls"><input id="search" type="search" aria-label="Search" placeholder="Search icons or issues"><select id="filter" aria-label="Result"><option value="">All 50</option><option value="repaired">Repaired</option><option value="unresolved">Unresolved</option></select><a href="audit.json">Detailed audit</a></div><p id="visible"></p></header><main>'''+''.join(cards)+'''</main><dialog id="comparison"><button class="close">Close</button><div class="content"></div></dialog><script>
const cards=[...document.querySelectorAll('article')],q=document.getElementById('search'),f=document.getElementById('filter'),dialog=document.getElementById('comparison');function filter(){let n=0;for(const c of cards){c.hidden=!((!f.value||f.value===c.dataset.outcome)&&c.textContent.toLowerCase().includes(q.value.toLowerCase()));if(!c.hidden)n++;}document.getElementById('visible').textContent=n+' of 50 shown';}q.addEventListener('input',filter);f.addEventListener('change',filter);for(const c of cards)c.querySelector('.enlarge').onclick=()=>{const copy=c.cloneNode(true);copy.hidden=false;copy.querySelector('details').open=true;dialog.querySelector('.content').replaceChildren(copy);dialog.showModal();};dialog.querySelector('.close').onclick=()=>dialog.close();filter();
</script></html>'''
(W/'index.html').write_text(page)
print('Review gallery:',W/'index.html')
